from video_helpers import *

class EvidenceTests(FixtureCase):
    def test_synthetic_healthy_checks_only(self):r=self.run_eval();self.assertEqual(r.status,'CHECKS_PASSED');self.assertFalse(r.product_accepted)
    def test_unsigned_requires_review(self):self.assertEqual(self.run_eval(authenticated=False).status,'REVIEW_REQUIRED')
    def test_declared_report_not_actual_media_proof(self):self.assertFalse(self.run_eval().to_dict()['full_media_quality_verified'])
    def test_changed_video_bytes(self):(self.root/'movie.mp4').write_bytes(b'changed');self.check_code('ARTIFACT_SIZE_MISMATCH')
    def test_same_size_video_change(self):p=self.root/'movie.mp4';p.write_bytes(b'x'*p.stat().st_size);self.check_code('ARTIFACT_HASH_MISMATCH')
    def test_missing_input(self):(self.root/'input.ts').unlink();self.check_code('ARTIFACT_OPEN_OR_READ_FAILED')
    def test_changed_build_bytes(self):(self.root/'output.js').write_bytes(b'changed');self.check_code('ARTIFACT_SIZE_MISMATCH')
    def test_wrong_input_scope(self):self.check_code('VIDEO_INPUT_INVENTORY',p=replace(self.p,expected_input_digest='9'*64))
    def test_wrong_composition(self):self.check_code('VIDEO_COMPOSITION_SCOPE',p=replace(self.p,composition_id='other'))
    def test_failed_compile(self):self.check_code('VIDEO_EXECUTION_FAILED',r=self.receipt('compile',exit_code=2))
    def test_failed_render(self):self.check_code('VIDEO_EXECUTION_FAILED',r=self.receipt('render',exit_code=1))
    def test_compile_not_started(self):self.check_code('VIDEO_EXECUTION_FAILED',r=self.receipt('compile',started=False))
    def test_render_timeout(self):self.check_code('VIDEO_EXECUTION_FAILED',r=self.receipt('render',timed_out=True))
    def test_receipt_run_mismatch(self):self.check_code('VIDEO_RECEIPT_BINDING',r=self.receipt('render',run_id='another'))
    def test_receipt_revision_mismatch(self):self.check_code('VIDEO_RECEIPT_BINDING',r=self.receipt('compile',revision='b'*40))
    def test_receipt_future(self):self.check_code('VIDEO_RECEIPT_STALE',r=self.receipt('compile',issued_at=NOW+1))
    def test_receipt_expired(self):self.check_code('VIDEO_RECEIPT_STALE',r=self.receipt('render',issued_at=NOW-3601))
    def test_unapproved_tool(self):self.check_code('VIDEO_TOOL_POLICY',r=self.receipt('compile',tool_id='unapproved'))
    def test_reported_is_not_native(self):self.check_code('VIDEO_NON_NATIVE_RECEIPT',r=self.receipt('compile',execution_kind='reported'))
    def test_diagnostic_is_not_native(self):self.check_code('VIDEO_NON_NATIVE_RECEIPT',r=self.receipt('render',execution_kind='diagnostic'))
    def test_compile_input_digest(self):self.check_code('VIDEO_COMPILE_ARTIFACT_LINK',r=self.receipt('compile',inputs_digest='0'*64))
    def test_compile_output_digest(self):self.check_code('VIDEO_COMPILE_ARTIFACT_LINK',r=self.receipt('compile',outputs_digest='0'*64))
    def test_render_input_digest(self):self.check_code('VIDEO_RENDER_ARTIFACT_LINK',r=self.receipt('render',inputs_digest='0'*64))
    def test_render_output_digest(self):self.check_code('VIDEO_RENDER_ARTIFACT_LINK',r=self.receipt('render',outputs_digest='0'*64))
    def test_render_parent_digest(self):self.check_code('VIDEO_RENDER_ARTIFACT_LINK',r=self.receipt('render',parent_receipt_sha256='0'*64))
    def test_smoke_not_full(self):self.check_code('VIDEO_PARTIAL_RENDER',r=self.receipt('render',mode='smoke'))
    def test_partial_frame_range(self):self.check_code('VIDEO_PARTIAL_RENDER',r=self.receipt('render',first_frame=1))
    def test_receipt_frame_count(self):self.check_code('VIDEO_PARTIAL_RENDER',r=self.receipt('render',frame_count=7))
    def test_compile_mode(self):self.check_code('VIDEO_COMPILE_SCOPE',r=self.receipt('compile',mode='full'))
    def test_compile_not_render(self):self.check_code('VIDEO_COMPILE_SCOPE',r=self.receipt('compile',frame_count=8))
    def test_compile_error_hidden_by_exit_zero(self):
        log=self.put('log-0',encode_log(b'input.ts(1,1): error TS2322: wrong type'),'logs/0.json');self.check_code('VIDEO_COMPILER_DIAGNOSTICS',r=self.receipt('compile',stdout=log))
    def test_log_tamper(self):(self.root/'logs/1.json').write_bytes(b'changed');self.check_code('ARTIFACT_SIZE_MISMATCH')
    def test_stderr_requires_review(self):
        log=self.put('log-1',encode_log(b'warning'),'logs/1.json');self.check_code('VIDEO_STDERR_REVIEW',r=self.receipt('compile',stderr=log))
    def test_missing_audio(self):self.check_code('VIDEO_REQUIRED_AUDIO_MISSING',p=replace(self.p,require_audio=True))
    def test_decode_failure_propagates(self):
        with patch('bie.qa.video_v2.evaluator.inspect_bytes',side_effect=ContractError('VIDEO_DECODE_FAILED')):
            r=evaluate(self.r,self.root,self.p,as_of=NOW)
        self.assertEqual(r.decoded_frame_count,0);self.assertEqual(r.status,'BLOCKED')
    def test_requested_count_cannot_replace_actual(self):self.check_code('VIDEO_FRAME_COUNT',obs=replace(self.obs,frames=self.obs.frames[:-1],pts=self.obs.pts[:-1],durations=self.obs.durations[:-1]))
    def test_no_frame_sampling_invention(self):self.check_code('VIDEO_REQUIRED_SAMPLE_MISSING',obs=replace(self.obs,frames=self.obs.frames[:2],pts=(0,1),durations=(1,1)))
    def test_report_replay(self):self.assertEqual(self.run_eval().to_dict(),self.run_eval().to_dict())

class PixelTests(FixtureCase):
    def test_black_frame_middle(self):f=list(self.obs.frames);f[3]=bytes(32*24*3);self.check_code('VIDEO_UNAPPROVED_BLANK',obs=replace(self.obs,frames=tuple(f)))
    def test_white_frame(self):f=list(self.obs.frames);f[3]=b'\xff'*(32*24*3);self.check_code('VIDEO_UNAPPROVED_BLANK',obs=replace(self.obs,frames=tuple(f)))
    def test_flat_color_frame(self):f=list(self.obs.frames);f[3]=bytes((90,20,40))*(32*24);self.check_code('VIDEO_UNAPPROVED_BLANK',obs=replace(self.obs,frames=tuple(f)))
    def test_approved_blank(self):
        f=list(self.obs.frames);f[3]=bytes(32*24*3);r=self.run_eval(p=replace(self.p,blank_allowances=(Window(3,4),)),obs=replace(self.obs,frames=tuple(f)));self.assertNotIn('VIDEO_UNAPPROVED_BLANK',self.codes(r))
    def test_blank_window_half_open(self):f=list(self.obs.frames);f[4]=bytes(32*24*3);self.check_code('VIDEO_UNAPPROVED_BLANK',p=replace(self.p,blank_allowances=(Window(3,4),)),obs=replace(self.obs,frames=tuple(f)))
    def test_freeze_required_movement(self):self.check_code('VIDEO_FROZEN_REQUIRED_MOTION',obs=replace(self.obs,frames=(self.obs.frames[0],)*8))
    def test_no_motion_assumption(self):r=self.run_eval(p=replace(self.p,expected_motion=()),obs=replace(self.obs,frames=(self.obs.frames[0],)*8));self.assertNotIn('VIDEO_FROZEN_REQUIRED_MOTION',self.codes(r));self.assertIn('VIDEO_MOTION_EXPECTATIONS_ABSENT',self.codes(r))
    def test_unapproved_cut(self):self.check_code('VIDEO_UNAPPROVED_DISCONTINUITY',p=replace(self.p,abrupt_change_ppm=1))
    def test_approved_cuts(self):r=self.run_eval(p=replace(self.p,abrupt_change_ppm=1,cuts=tuple(range(1,8))));self.assertNotIn('VIDEO_UNAPPROVED_DISCONTINUITY',self.codes(r))
    def test_crop_overflow_left(self):reg=replace(self.p.regions[0],x=-1);self.check_code('VIDEO_REGION_OVERFLOW',p=replace(self.p,regions=(reg,)))
    def test_crop_overflow_right(self):reg=replace(self.p.regions[0],x=31);self.check_code('VIDEO_REGION_OVERFLOW',p=replace(self.p,regions=(reg,)))
    def test_crop_overflow_bottom(self):reg=replace(self.p.regions[0],y=23);self.check_code('VIDEO_REGION_OVERFLOW',p=replace(self.p,regions=(reg,)))
    def test_required_template_mismatch(self):reg=replace(self.p.regions[0],x=20);self.check_code('VIDEO_REQUIRED_REGION_MISMATCH',p=replace(self.p,regions=(reg,)))
    def test_no_crop_templates(self):self.check_code('VIDEO_CROP_COVERAGE_MISSING',p=replace(self.p,regions=()))
    def test_changed_template_bytes(self):(self.root/'template.png').write_bytes(b'corrupt');self.check_code('ARTIFACT_SIZE_MISMATCH')
    def test_sampling_budget_fail_closed(self):self.check_code('VIDEO_SAMPLE_BUDGET',p=replace(self.p,max_samples=1))
